root=pathlib.Path("tools/core20k_sense_v1/release/v21-missing-batch500-all")
batchroot=pathlib.Path("tools/core20k_sense_v1/release/v21-missing-batch500-all")
entries=json.loads(r'''{"newsstand":["报刊亭","She bought a newspaper at the ___.","报刊亭"],"rowing":["赛艇运动","He took up ___ at university.","赛艇"],"fjord":["峡湾","The ship sailed slowly through the Norwegian ___.","峡湾"],"ebullient":["热情洋溢的","Her ___ personality energized the whole team.","热情洋溢"],"immunofluorescence":["免疫荧光技术","The lab used ___ to visualize proteins in the tissue.","免疫荧光"],"pothole":["道路坑洞","The cyclist swerved to avoid a deep ___.","路面坑洞"],"uninitiated":["外行的；未经入门的","The manual is confusing to the ___.","外行者"],"cloudless":["万里无云的","The astronomers observed a ___ night sky.","无云"],"sidekick":["忠实伙伴","The detective and his ___ solved the mystery.","伙伴"],"sorrowful":["悲伤的","She gave a ___ farewell to her friends.","悲伤"],"cajole":["哄劝；劝诱","They tried to ___ him into joining the club.","哄劝"],"shard":["碎片","The archaeologist found a pottery ___ in the soil.","陶器碎片"],"inkling":["隐约的想法","I had no ___ that the plan would change.","隐约想法"],"behest":["命令；要求","The changes were made at the director's ___.","要求"],"biplane":["双翼飞机","The museum restored a historic ___.","双翼飞机"],"wellington":["高筒靴","The collector displayed an antique leather ___.","高筒靴"],"votive":["还愿奉献的","Visitors lit a ___ candle at the shrine.","还愿的"],"embolden":["使鼓起勇气","The early success helped ___ the volunteers.","鼓舞"],"reputedly":["据说","The painting was ___ discovered in an attic.","据说"],"linearly":["线性地","The measured signal increased ___ with time.","线性"],"newt":["蝾螈","A small ___ hid beneath the stones.","蝾螈"],"underrate":["低估","Do not ___ the difficulty of the climb.","低估"],"townsfolk":["镇民","The ___ gathered for the annual festival.","镇民"],"amiably":["和蔼地","The host smiled ___ at the guests.","和蔼"],"semifinal":["半决赛","Her team reached the ___ of the tournament.","半决赛"],"powerlessness":["无力感","The failure left him with a sense of ___.","无力"],"rapturous":["狂喜的","The audience gave the musicians a ___ welcome.","狂喜"],"mangrove":["红树林树木","The researchers studied a ___ along the tropical coast.","红树"],"candlestick":["烛台","An old silver ___ stood on the table.","烛台"],"ferociously":["凶猛地","The dog barked ___ at the stranger.","凶猛"],"capacious":["容量大的","The traveler packed everything into a ___ bag.","容量大"],"definiteness":["明确性","The lawyer questioned the ___ of the agreement.","明确"],"naivete":["天真；幼稚","His ___ made him easy to deceive.","天真"],"newfound":["新发现的","She explored her ___ confidence after the competition.","新获得"],"pittance":["微薄报酬","The workers received a ___ for their labor.","微薄报酬"],"vestment":["宗教礼服","The priest wore a ceremonial ___.","宗教礼服"],"flabby":["松弛无力的","Months without exercise left his muscles ___.","松弛"],"expunge":["抹去；删除","The court agreed to ___ the outdated record.","删除"],"superhuman":["超人的","The rescue demanded almost ___ strength.","超人的"],"sadistic":["施虐成性的","The villain displayed a ___ delight in cruelty.","施虐"],"herbivore":["食草动物","A giraffe is a large ___.","食草动物"],"wistfully":["惆怅地","She looked ___ at the childhood photograph.","惆怅"],"gentlemanly":["彬彬有礼的","His ___ behavior impressed the visitors.","有礼貌"],"parsonage":["牧师住宅","The church repaired the old ___.","牧师住宅"],"egregious":["极其恶劣的","The audit uncovered an ___ violation.","极恶劣"],"sensuous":["诉诸感官的；感官愉悦的","The painting has a rich, ___ quality.","感官愉悦"],"doorman":["门卫","The hotel ___ opened the door for guests.","门卫"],"hubris":["狂妄自大","The leader's ___ contributed to his downfall.","自大"],"camping":["露营","They went ___ beside the lake.","露营"],"compunction":["内疚；懊悔","He showed no ___ about breaking the promise.","内疚"],"starlight":["星光","They walked home by ___.","星光"],"frenchman":["法国男子","The novel's hero was a young ___.","法国男子"],"dispassionate":["冷静客观的","The judge gave a ___ assessment of the evidence.","客观"],"artistry":["艺术技艺","The dancer's ___ impressed the critics.","艺术技艺"],"colloquial":["口语化的","The dialogue uses ___ expressions.","口语"],"unman":["使失去勇气","The sudden disaster threatened to ___ him.","使丧失勇气"],"perspire":["出汗","People tend to ___ more in hot weather.","出汗"],"brazier":["火盆","The workers warmed their hands over a ___.","火盆"],"terry":["毛圈织物","The towels were made from soft ___.","毛圈织物"],"unstressed":["非重读的","The vowel in the second syllable is ___.","非重读"],"milkman":["送奶工","The ___ delivered bottles each morning.","送奶工"],"neuropsychological":["神经心理学的","The patient completed a ___ assessment.","神经心理学"],"forebear":["祖先","The family traced one ___ back to Scotland.","祖先"],"canny":["精明的；审慎的","The ___ investor avoided the risky deal.","精明"],"schoolroom":["教室","The pupils returned to the ___.","教室"],"thistle":["蓟属植物","A purple ___ grew beside the path.","蓟"],"hyperbole":["夸张修辞","The writer used ___ to emphasize the point.","夸张"],"cuddly":["让人想抱的","The child hugged a ___ toy bear.","可爱柔软"],"impulsively":["冲动地","He ___ bought a ticket without checking the date.","冲动"],"bassoon":["巴松管","She played the ___ in the orchestra.","巴松管"],"tiara":["冠状头饰","The performer wore a jeweled ___.","头冠"],"carpentry":["木工活","He learned ___ from his grandfather.","木工"],"despondent":["沮丧绝望的","The team felt ___ after another defeat.","沮丧"],"croft":["小农场","The family maintained a small ___ on the island.","小农场"],"panoply":["琳琅满目的一整套","The exhibition displayed a ___ of historical costumes.","全套"],"irrepressible":["无法抑制的","Her ___ laughter filled the room.","无法抑制"],"circumspect":["谨慎周到的","The board took a ___ approach to the merger.","谨慎"],"derivational":["派生构词的","The linguist analyzed ___ suffixes.","派生构词"],"montage":["蒙太奇拼贴","The director created a ___ of archival images.","蒙太奇"],"desultory":["漫无目的的；不连贯的","The meeting drifted into a ___ conversation.","漫无目的"],"imperfectly":["不完美地","The instrument reproduced the sound ___.","不完美"],"bonny":["漂亮的（英式/苏格兰）","The old song describes a ___ child.","漂亮"],"maestro":["大师；指挥家","The orchestra welcomed the visiting ___.","大师"],"unpopularity":["不得人心","The policy's ___ surprised the minister.","不得人心"],"ducal":["公爵的","The historian visited the ___ palace.","公爵"],"participle":["分词","The teacher explained the past ___.","分词"],"transgene":["转基因导入基因","The scientists monitored the inserted ___ in plants.","转基因"],"undifferentiated":["未分化的","The sample contained ___ stem cells.","未分化"],"phoenix":["凤凰","The legend tells of a ___ rising from ashes.","凤凰"],"gramophone":["留声机","The antique ___ played an old record.","留声机"],"irreconcilable":["不可调和的","The two groups held ___ views.","无法调和"],"taciturn":["沉默寡言的","The ___ guard rarely spoke.","寡言"],"incredulous":["难以置信的","She gave him an ___ look.","难以相信"],"blameless":["无可指责的","The inquiry found the driver ___.","无过错"],"infertile":["不育的；贫瘠的","The farmers struggled with ___ soil.","贫瘠"],"sourly":["不悦地","He ___ remarked on the delay.","不悦"],"overjoy":["使狂喜","The news will ___ the whole family.","使狂喜"],"mesa":["平顶山","The hikers climbed toward the distant ___.","平顶山"],"luminary":["杰出人物","The conference honored a scientific ___.","杰出人物"],"perusal":["细读","The report was submitted for the committee's ___.","细读"],"rancor":["怨恨","The argument left lasting ___ between colleagues.","怨恨"]}''')
allowed={r["lemma"]:r for line in (root/"next500_uncovered_source_cards.jsonl").open(encoding="utf8") for r in [json.loads(line)]}
assert set(entries).issubset(set(allowed)), "Attempted authoring of a word outside CURRENT deduplicated next500 source"
index=json.loads((batchroot/"index.json").read_text())
by_lemma={}
for b in index["batches"]:
    f=batchroot/("batch%03d"%b["batch"])/"bilingual_ku_editorial_candidates.jsonl"
    for line in f.open(encoding="utf8"):
        r=json.loads(line)
        if r["lemma"] in entries and r["editing_state"]=="EDITORIAL_SINGLE_GLOSS_CANDIDATE":
            by_lemma.setdefault(r["lemma"],[]).append(r)
with gzip.open("data/core20k-runtime.json.gz","rt",encoding="utf8") as f:
    words=json.load(f)["headwords"]
out=[];skipped={}
for lemma,(zh,prompt,cue) in entries.items():
    candidates=by_lemma.get(lemma,[])
    if len(candidates)!=1:
        skipped[lemma]="NOT_EXACTLY_ONE_LOW_RISK_SOURCE";continue
    r=candidates[0];rank=r["rank"]
    assert allowed[lemma]["rank"]==rank and allowed[lemma]["oewn_sense_id"]==r["oewn_sense_id"]
    assert words[rank-1][1].casefold()==lemma and prompt.count("___")==1
    response=lemma.title() if lemma in {"october","january","june","february","november","december","september","april","monday"} else lemma
    out.append({"draft_sense_id":f"staging:v21:bilingual:{rank}:{r['oewn_sense_id']}",
      "headword_id":f"core20k:rank:{rank}","rank":rank,"lemma":lemma,
      "oewn_sense_id":r["oewn_sense_id"],"definition_en_source":r["definition_en"],
      "gloss_zh_editorial":zh,"ecdict_wordlevel_reference":r["translation_zh_wordlevel_source"],
      "draft_ku_id":f"staging:v21:missing:{rank}:editorial16",
      "ku_type":"sense","render_kind":"guided_cloze",
      "question_instruction_zh":f"根据“{cue}”补全英文句子。",
      "prompt":prompt,"context_en":prompt.replace("___",response),
      "correct_answer":response,"acceptable_answers":[response],
      "source_attribution":"OEWN2025 exact Sense + ECDICT word-level evidence + original AI editorial context",
      "review_status":"AI_BILINGUAL_EDITORIAL_NEEDS_INDEPENDENT_SEMANTIC_AND_ASSESSMENT_QA",
      "independent_semantic_certified":False,"release_eligible":False,"production_ready":False})
assert len(out)>0 and len({x["draft_ku_id"] for x in out})==len(out)
dest=root/"bilingual_sense_ku_curated_batch16.jsonl"
dest.write_text("".join(json.dumps(r,ensure_ascii=False)+"\n" for r in out),encoding="utf8")
print("BILINGUAL_CURATED_BATCH16_PASS",json.dumps({"authored":len(entries),"new_bilingual_editorial_senses":len(out),"new_original_context_kus":len(out),"skipped":skipped,"independent_certified":0,"production_ready":0},ensure_ascii=False))
